package exercise

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func makeDelayedServer(delay time.Duration) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(delay)
		w.WriteHeader(http.StatusOK)
	}))
}

func TestRacer(t *testing.T) {
	slow := makeDelayedServer(30 * time.Millisecond)
	fast := makeDelayedServer(0)
	defer slow.Close()
	defer fast.Close()

	got, err := Racer(slow.URL, fast.URL)

	if err != nil {
		t.Fatalf("did not expect an error but got one: %v", err)
	}
	if got != fast.URL {
		t.Errorf("got %q, want %q", got, fast.URL)
	}
}

func TestConfigurableRacerReturnsTheFasterURL(t *testing.T) {
	slow := makeDelayedServer(30 * time.Millisecond)
	fast := makeDelayedServer(0)
	defer slow.Close()
	defer fast.Close()

	got, err := ConfigurableRacer(fast.URL, slow.URL, 500*time.Millisecond)

	if err != nil {
		t.Fatalf("did not expect an error but got one: %v", err)
	}
	if got != fast.URL {
		t.Errorf("got %q, want %q", got, fast.URL)
	}

	got, err = ConfigurableRacer(slow.URL, fast.URL, 500*time.Millisecond)

	if err != nil {
		t.Fatalf("did not expect an error but got one: %v", err)
	}
	if got != fast.URL {
		t.Errorf("got %q, want %q", got, fast.URL)
	}
}

func TestConfigurableRacerTimesOut(t *testing.T) {
	server := makeDelayedServer(60 * time.Millisecond)
	defer server.Close()

	got, err := ConfigurableRacer(server.URL, server.URL, 10*time.Millisecond)

	if err == nil {
		t.Fatal("expected an error but did not get one")
	}
	if got != "" {
		t.Errorf("expected no winner on a timeout, got %q", got)
	}
}

func TestConfigurableRacerPingsBothURLsAtTheSameTime(t *testing.T) {
	slow := makeDelayedServer(60 * time.Millisecond)
	fast := makeDelayedServer(0)
	defer slow.Close()
	defer fast.Close()

	start := time.Now()

	if _, err := ConfigurableRacer(slow.URL, fast.URL, 500*time.Millisecond); err != nil {
		t.Fatalf("did not expect an error but got one: %v", err)
	}

	if elapsed := time.Since(start); elapsed >= 60*time.Millisecond {
		t.Errorf("the two urls were not requested at the same time, the race took %v", elapsed)
	}
}

